private void enlarge(final int size) {
    int curCapacity = this.data.length;
    int minCapacity = this.size + size;
    if (minCapacity <= curCapacity) {
        return;
    }
    int newCapacity = curCapacity + ((curCapacity >> 1) + (curCapacity >> 2));
    if (newCapacity < minCapacity) {
        newCapacity = minCapacity;
    }
    byte[] oldData = this.data;
    this.data = new byte[newCapacity];
    System.arraycopy(oldData, 0, this.data, 0, this.size);
}

public void enlarge(final int size){
    // Check if resize is needed
    if(this.bytes.length - this.byteUsed >= size){
        return;
    }
    // Calculate new length
    int newLength = this.bytes.length * 2;
    while (newLength - this.byteUsed < size) {
        newLength = newLength * 2;
    }
    // Create new byte array
    byte[] newBytes = new byte[newLength];
    // Copy old bytes to new bytes
    System.arraycopy(this.bytes, 0, newBytes, 0, this.byteUsed);
    // Update bytes and byteUsed
    this.bytes = newBytes;
    this.byteUsed = newLength;
}

public void enlarge(final int size) {
    // initialize a new byte array with the size
    byte[] newData = new byte[size];

    // copy the existing data into the new array
    System.arraycopy(this.data, 0, newData, 0, this.data.length);

    // set the new data
    this.data = newData;
}

