public TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> newParent = node.getLeftChild();
    node.setLeftChild(newParent.getRightChild());
    newParent.setRightChild(node);
    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> temp = node.left;
    node.left = temp.right;
    temp.right = node;
    temp.numNodes += node.numNodes;
    node.numNodes -= temp.numNodes;
    return temp;
}

