    public static void addToClassPath(Vector<URL> cpV, String dir) {
        File[] jars = new File(dir).listFiles();
        if (jars != null) {
            for (File jar : jars) {
                try {
                    URL url = new URL(jar.toURI().toURL().toString());
                    if (!cpV.contains(url)) {
                        cpV.add(url);
                    }
                } catch (MalformedURLException e) {
                    e.printStackTrace();
                }
            }
        }
    }

public static void addToClassPath(Vector<URL> cpV, String dir) {
    File d = new File(dir);
    File[] files = d.listFiles();
    for (File f : files) {
        try {
            URL u = f.toURI().toURL();
            cpV.add(u);
        } catch (Exception e) {
            System.err.println("Error adding to classpath: " + e);
        }
    }
}

public void addToClassPath(Vector<URL> cpV, String dir) {
    File file = new File(dir);
    File[] files = file.listFiles();
    if (files != null) {
        for (File f : files) {
            if (f.getName().endsWith(".jar")) {
                try {
                    cpV.add(f.toURI().toURL());
                } catch (MalformedURLException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
	try {
		File f = new File(dir);
		String[] files = f.list();
		for (String file : files) {
			if (file.endsWith(".jar")) {
				File f2 = new File(dir + File.separator + file);
				cpV.add(f2.toURI().toURL());
			}
		}
	} catch (Exception e) {
		e.printStackTrace();
