public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.sizeof(message, buffer);
    int sizeSize = CodedOutputStream.computeRawVarint32Size(size);
    int totalSize = size + sizeSize;
    LinkedBuffer buffer = buffer;
    if (buffer.capacity < totalSize) {
        buffer.reset();
    }
    buffer.writeRawVarint32(size);
    schema.writeTo(message, buffer);
    out.write(buffer.byteArray, 0, totalSize);
    return totalSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    byte[] bytes = new byte[size + 10]; // Allocate space for the length prefix
    bytes[0] = (byte) (size >>> 24);
    bytes[1] = (byte) (size >>> 16);
    bytes[2] = (byte) (size >>> 8);
    bytes[3] = (byte) (size >>> 0);
    schema.writeTo(message, bytes, 4, buffer);
    out.write(bytes);
    return size;
}

