public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedTypes = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            Class<?> resolvedType = null;
            if (typeArgument instanceof Class) {
                resolvedType = (Class<?>) typeArgument;
            } else if (typeArgument instanceof TypeVariable) {
                TypeVariable typeVariable = (TypeVariable) typeArgument;
                resolvedType = resolveTypeVariable(typeVariable, targetType);
            } else if (typeArgument instanceof WildcardType) {
                WildcardType wildcardType = (WildcardType) typeArgument;
                Type[] upperBounds = wildcardType.getUpperBounds();
                Type[] lowerBounds = wildcardType.getLowerBounds();
                if (upperBounds.length == 1 && lowerBounds.length == 0) {
                    resolvedType = resolveTypeVariable(upperBounds[0], targetType);
                } else if (upperBounds.length == 0 && lowerBounds.length == 1) {
                    resolvedType = resolveTypeVariable(lowerBounds[0], targetType);
                }
            }
            if (resolvedType != null) {
                resolvedTypes[i] = resolvedType;
            }
        }
        return resolvedTypes;
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the generic type is a parameterized type
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();

    // Check if the type arguments are present
    if (typeArguments.length == 0) {
        return null;
    }

    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];

    // Resolve each type argument
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            // If the type argument is a class, we can use it directly
            resolvedArguments[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof ParameterizedType) {
            // If the type argument is a parameterized type, we need to resolve it
            resolvedArguments[i] = resolveArguments((ParameterizedType) typeArgument, targetType);
        } else if (typeArgument instanceof TypeVariable) {
            // If the type argument is a type variable, we need to replace it with its actual type
            TypeVariable typeVariable = (TypeVariable) typeArgument;
            TypeVariable[] typeParameters = targetType.getTypeParameters();
            for (int j = 0; j < typeParameters.length; j++) {
                if (typeParameters[j].equals(typeVariable)) {
                    resolvedArguments[i] = (Class<?>) typeParameters[j].getBounds()[0];
                    break;
                }
            }
        } else {
            // If the type argument is not a class, parameterized type, or type variable, we can't resolve it
            return null;
        }
    }

    return resolvedArguments;
}

