public static long compressTimeBucket(long timeBucket,int dayStep) {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("uuuuMMdd");
        LocalDateTime dateTime = LocalDateTime.parse(String.valueOf(timeBucket), formatter);
        dateTime = dateTime.truncatedTo(ChronoUnit.DAYS);

        long result = dateTime.plusDays(dayStep - 1).toEpochSecond(0, 0);

        return result;
    }

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Convert the long value to a LocalDate object
    LocalDate date = Instant.ofEpochMilli(timeBucket).atZone(ZoneOffset.UTC).toLocalDate();

    // Calculate the difference between the current date and the start of the month
    int dayOffset = date.getDayOfMonth() - 1;

    // Calculate the start of the next month
    LocalDate nextMonthStartDate = date.plusMonths(1);

    // Calculate the difference between the start of the next month and the start of the current month
    int nextMonthOffset = nextMonthStartDate.getDayOfMonth() - 1;

    // Calculate the re-formatted time bucket
    long reformattedTimeBucket = timeBucket - dayOffset + (dayStep * nextMonthOffset);

    return reformattedTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long compressedTimeBucket = timeBucket / 10000L * 10000L + (timeBucket % 10000L / dayStep) * dayStep;
    return compressedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int count = 0;
    for (int i = index; i < len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            count++;
        } else if (ch <= 0x7FF) {
            count += 2;
        } else if (Character.isHighSurrogate(ch)) {
            count += 4;
            ++i;
        } else {
            count += 3;
        }
    }
    return count;
}

