    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        PathSegmentImpl pathSegment = new PathSegmentImpl();
        pathSegment.setName(segment);
        if (decode) {
            pathSegment.setPath(URLDecoder.decode(segment, StandardCharsets.UTF_8));
        } else {
            pathSegment.setPath(segment);
        }
        pathSegments.add(pathSegment);
    }
    return pathSegments;
}

