        String segment = path.get(i);
        String decodedSegment = decode ? URLDecoder.decode(segment, "UTF-8") : segment;

        // If the first segment is an absolute path, remove it
        if (i == 0 && decodedSegment.startsWith("/")) {
            decodedSegment = decodedSegment.substring(1);
        }

        // Add the segment to the result list
        result.add(new PathSegmentImpl(decodedSegment, lastSegmentEnd, lastSegmentEnd + decodedSegment.length()));
        lastSegmentEnd += decodedSegment.length();
    }

    return result;
}

