}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        int nodeSize = node.length();
        out.write(node.read(nodeSize));
        totalSize += nodeSize;
        node = node.next;
    }
    return totalSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // Initialize a variable to keep track of the total content size
    int totalSize = 0;

    // Traverse the LinkedBuffer and write each node to the DataOutput
    for (Node current = node; current != null; current = current.getNext()) {
        totalSize += out.write(current.getByteArray(), current.getOffset(), current.getLength());
    }

    // Return the total size of the buffer
    return totalSize;
}

