        throw new NullPointerException("b cannot be null");
    }
    int position = 0;
    while (position < b.length) {
        int bytesToWrite = Math.min(buffer.length - position, b.length - position);
        System.arraycopy(b, position, buffer, position, bytesToWrite);
        position += bytesToWrite;
        if (position >= buffer.length) {
            flush();
            position = 0;
        }
    }
}

