public Object toString(JSONWriter.Feature... features) {
    //Validation
    if (features == null) {
        throw new NullPointerException("Parameter 'features' cannot be null.");
    }

    //Array sorted to be checked correctly
    if (features.length == 0) {
    return "";
    }

    //Order features by their names
    Arrays.sort(features, (f1, f2) -> f1.name().compareTo(f2.name()));

    //Convert features to JSON
    JSONObject json = new JSONObject();
    for (JSONWriter.Feature feature : features) {
        json.put(feature.name(), feature.enabled());
    }

    return json.toString();
}

public String toString(JSONWriter.Feature... features) {
    JSONWriter writer = new JSONWriter();
    writer.setIndent(2);
    if (features != null && features.length > 0) {
        for (JSONWriter.Feature feature : features) {
            if (feature == JSONWriter.Feature.ESCAPE_NON_ASCII) {
                writer.setEscapeNonAscii();
            } else if (feature == JSONWriter.Feature.ESCAPE_ALL) {
                writer.setEscapeAll();
            } else if (feature == JSONWriter.Feature.META_API_CLASS) {
                writer.setMetaApiClass(true);
            } else if (feature == JSONWriter.Feature.META_API_METHOD) {
                writer.setMetaApiMethod(true);
            } else if (feature == JSONWriter.Feature.ALWAYS_QUOTE) {
                writer.setAlwaysQuote(true);
            } else if (feature == JSONWriter.Feature.ALWAYS_STRING) {
                writer.setAlwaysString(true);
            }
        }
    }
    return writer.writeValueAsString(this);
}

public String toString(JSONWriter.Feature... features) {
    // Create a JSONObject to store the features
    JSONObject obj = new JSONObject();
    // Iterate through the features and add them to the JSONObject
    for (JSONWriter.Feature feature : features) {
        obj.put(feature.getName(), feature.getValue());
    }
    // Return the JSON string representation of the JSONObject
    return obj.toString();
}

public String toString(JSONWriter.Feature... features) {
    ObjectMapper mapper = new ObjectMapper();
    mapper.enable(JSONWriter.Feature.SORT_PROPERTIES_ALPHABETICALLY);
    StringBuilder sb = new StringBuilder();
    Arrays.stream(features).forEach(f -> sb.append(f.name()).append(","));
    try {
        String json = mapper.writeValueAsString(this);
        return sb.toString() + json;
    } catch (JsonProcessingException e) {
        throw new RuntimeException(e);
    }
}

