public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1000) {
        return 11 * ((desiredCapacity + 10) / 11);
    }
    int rem = desiredCapacity % 11;
    int lower = (rem == 0) ? desiredCapacity / 11 : (desiredCapacity / 11) + 1;
    int upper = (rem == 0) ? (desiredCapacity / 11) - 1 : desiredCapacity / 11;
    if (lower < 9 * upper) {
        while (!isPrime(lower)) {
            lower++;
        }
    } else {
        while (!isPrime(upper)) {
            upper--;
        }
    }
    return 11 * upper;
}

