    // Start with the smallest prime greater than the desired capacity
    int prime = 2;
    while (prime < desiredCapacity) {
        prime++;
        if (isPrime(prime)) {
            break;
        }
    }
    return prime;
}

public static int nextPrime(int desiredCapacity) {
    int capacity = (int) (desiredCapacity / 0.875);
    boolean isPrime = false;
    while (!isPrime) {
        capacity++;
        isPrime = true;
        for (int i = 2; i < capacity; i++) {
            if (capacity % i == 0) {
                isPrime = false;
                break;
            }
        }
    }
    return capacity;
}

