public static String unescapeJava(String str) throws Exception {
	if (str == null) {
		return null;
	}
	StringBuilder sb = new StringBuilder();
	boolean escaping = false;
	for (int i = 0; i < str.length(); i++) {
		char ch = str.charAt(i);
		if (escaping) {
			if (ch == '\\' || ch == 'n') {
				sb.append(ch);
			} else if (ch == 'r') {
				sb.append('\r');
			} else if (ch == 't') {
				sb.append('\t');
			} else {
				sb.append('\\').append(ch);
			}
			escaping = false;
		} else {
			if (ch == '\\') {
				escaping = true;
			} else {
				sb.append(ch);
			}
		}
	}
	return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
        String result = str;
        if (str != null) {
            for (int i = 0; i < str.length(); i++) {
                char ch = str.charAt(i);
                if (ch == '\\') {
                    int nextIdx = i + 1;
                    if (nextIdx < str.length()) {
                        char nextCh = str.charAt(nextIdx);
                        if (nextCh == 'n') {
                            result = result.substring(0, i - 1) + '\n' + result.substring(nextIdx + 1);
                            i++;
                        } else if (nextCh == 'r') {
                            result = result.substring(0, i - 1) + '\r' + result.substring(nextIdx + 1);
                        } else if (nextCh == 't') {
                            result = result.substring(0, i - 1) + '\t' + result.substring(nextIdx + 1);
                        } else if (nextCh == 'f') {
                            result = result.substring(0, i - 1) + '\f' + result.substring(nextIdx + 1);
                        } else if (nextCh == 'e') {
                            result = result.substring(0, i - 1) + '\u007f' + result.substring(nextIdx + 1);
                        } else if (nextCh == 'u') {
                            // Unicode escape sequence
                            /*
                             * Read the hex value of the Unicode escape sequence and convert it to a character.
                            * Parse the next 4 characters after the 'u' and convert it to a Integer value using radix 16
                            * Finally, replace the escaped Unicode character with the corresponding integer value
                            */
                            String unicodeHexValue = str.substring(nextIdx + 1, nextIdx + 5);
                            int unicodeIntValue = Integer.parseInt(unicodeHexValue, 16);
                            result = result.substring(0, i - 1) + (char)unicodeIntValue + result.substring(nextIdx + 5);
                            i += 4;
                        }
                    }
                }
            }
        }
        return result;
    }

