public static String trimLeadingWhitespace(String str) {
    if (str == null || str.isEmpty()) {
        return str;
    }
    int len = str.length();
    for (int i = 0; i < len; i++) {
        if (!Character.isWhitespace(str.charAt(i))) {
            return str.substring(i);
        }
    }
    return str;
}

