}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.getNode() != null && !predicate.test(circulator.getNode())) {
        circulator.next();
    }
    if (circulator.getNode() == null) {
        circulator = new OuterFaceCirculator(stop, -dir);
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator that starts at the given start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    // Advance the circulator to the next node in the given direction
    circulator.move(dir);

    // Check if the next node satisfies the predicate
    Node next = circulator.get();
    if (!predicate.test(next)) {
        // If the next node does not satisfy the predicate, move the circulator to the opposite direction
        circulator.move(-dir);
        // Continue advancing the circulator until we reach the stop node
        while (!circulator.done() && !predicate.test(next)) {
            circulator.move(dir);
            next = circulator.get();
        }
    }

    // If we reached the stop node, return the stop node as the result
    if (circulator.done()) {
        return stop;
    }

    // Otherwise, return the node that satisfies the predicate
    return circulator.get();
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(dir, start);
    while (circulator.getCurrentNode() != stop) {
        if (predicate.test(circulator.getCurrentNode())) {
            return circulator;
        }
        circulator.moveToNext();
        if (circulator.getCurrentNode() == start) {
            circulator.setTarget(stop);
        }
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node curNode = start;
    while (curNode != stop) {
        if (predicate.test(curNode)) {
            return new OuterFaceCirculator(curNode, start);
        }
        curNode = curNode.getNeighbor(dir);
    }
    return new OuterFaceCirculator(stop, start);
}

