public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null) {
        return putNullBytes(byteLength);
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Second argument [" + byteOffset + "] must be >= 0 and <= the length of the input array [" + byteArrayValue.length + "]");
    }
    if (byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Third argument [" + byteLength + "] must be >= 0 and <= the length of the input array minus the offset [" + (byteArrayValue.length - byteOffset) + "]");
    }
    ensureCapacity(byteLength);
    System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
    size += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){

    if (byteArrayValue == null){
        ensureCapacity(byteOffset + byteLength);
        for (int i = byteOffset; i < byteOffset + byteLength; i++){
            this.data[i] = 0;
        }
        this.length = Math.max(this.length, byteOffset + byteLength);
        return this;
    }

    if (byteArrayValue.length != byteArrayValue.length){
        throw new IllegalArgumentException(
                "Invalid byte array length: " + byteArrayValue.length);
    }

    ensureCapacity(byteOffset + byteLength);
    System.arraycopy(byteArrayValue, byteOffset, this.data, byteOffset,
            byteLength);
    this.length = Math.max(this.length, byteOffset + byteLength);
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue != null) {
            if (this.length + byteLength <= this.data.length) {
                System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
                this.length += byteLength;
            } else {
                int newLength = Math.max(this.length << 1, this.length + byteLength);
                byte[] newData = new byte[newLength];
                System.arraycopy(this.data, 0, newData, 0, this.length);
                System.arraycopy(byteArrayValue, byteOffset, newData, this.length, byteLength);
                this.data = newData;
                this.length += byteLength;
            }
        } else {
            throw new NullPointerException("byteArrayValue");
        }
        return this;
    }

public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    // If the byte array is null, put null bytes into the byte vector
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            putByte((byte) 0);
        }
        return this;
    }

    // If the byte offset is greater than the length of the byte array, throw an exception
    if (byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset");
    }

    // If the byte length is greater than the length of the byte array, throw an exception
    if (byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength");
    }

    // Copy the bytes from the byte array into the byte vector
    for (int i = 0; i < byteLength; i++) {
        putByte(byteArrayValue[byteOffset + i]);
    }

    return this;
}

