if (r.transport() == AtmosphereResource.TRANSPORT.WEBSOCKET) {
   WebSocket webSocket = r.getRequest().getParameter("webSocket");
   webSocket.suspend();
} else if (r.transport() == AtmosphereResource.TRANSPORT.LONG_POLLING) {
