public Action inspect(AtmosphereResource r) {
    switch (r.getTransport()) {
    case WEBSOCKET:
    case SSE:
    case LONG_POLLING:
        r.suspend();
        return Action.CONTINUE;
    case JSONP:
    case STREAMING:
        return Action.CONTINUE;
    default:
        r.getBroadcaster().removeAtmosphereResource(r);
        return Action.CANCELLED;
    }
}

