WebsocketTransport webSocketTransport = r.getTransport(WebsocketTransport.class);
webSocketTransport.suspend();
}
else if (r.transport().equals(AtmosphereResource.TRANSPORT.STREAMING)){
LongPollingTransport longPollingTransport = r.getTransport(LongPollingTransport.class);
longPollingTransport.suspend();
}
