GraphPath<V,E> function(Set<E> tour, Graph<V,E> graph){
    List<E> edges = tour.toList();
    V start = edges.get(0).getSource();
    V end = edges.get(edges.size() - 1).getTarget();
    List<V> vertices = new ArrayList<V>();
    vertices.add(start);
    for (int i = 0; i < edges.size() - 1; i++) {
        vertices.add(edges.get(i).getTarget());
    }
    return new DefaultGraphPath<V,E>(graph, start, end, vertices, edges);
}

void edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    for (E edge : tour) {
        vertices.add(edge.getSource());
        vertices.add(edge.getDestination());
        edges.add(edge);
    }
    GraphPath<V, E> path = new DefaultGraphPath<>(vertices, edges, 0);
    return path;
 }

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
	List<V> vertices = new ArrayList<V>();
	List<E> edges = new ArrayList<E>();
	HashSet<V> visited = new HashSet<V>();
	for (E edge : tour) {
		if (!visited.contains(edge.getStart())) {
			vertices.add(edge.getStart());
		}
		if (!visited.contains(edge.getEnd())) {
			vertices.add(edge.getEnd());
		}
		edges.add(edge);
		visited.add(edge.getStart());
		visited.add(edge.getEnd());
	}
	return new GraphPath<V,E>(vertices, edges);
}

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    GraphPath<V,E> path = new GraphPath<V,E>(graph);
    Iterator<E> it = tour.iterator();
    if(it.hasNext()){
        E edge = it.next();
        path.addEdge(edge.getOutVertex(), edge.getInVertex());
    }
    while(it.hasNext()){
        E edge = it.next();
        path.addEdge(edge.getInVertex(), edge.getOutVertex());
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edges = new ArrayList<>(tour);
    List<V> vertices = new ArrayList<>();
    for (int i = 0; i < edges.size(); i++) {
        V source = graph.getEdgeSource(edges.get(i));
        V target = graph.getEdgeTarget(edges.get(i));
        if (!vertices.contains(source)) {
            vertices.add(source);
        }
        if (!vertices.contains(target)) {
            vertices.add(target);
        }
    }
    return new GraphWalk<>(graph, vertices, edges, 0);
}

