public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantPoolEntry entry = constantPool.get(i);
        if (entry.tag == ConstantPoolEntry.CONSTANT_NameAndType) {
            ConstantPoolEntry.NameAndTypeEntry nameAndType = (ConstantPoolEntry.NameAndTypeEntry) entry;
            if (nameAndType.name.equals(name) && nameAndType.descriptor.equals(descriptor)) {
                return nameAndType.nameAndType;
            }
        }
    }

    // Create a new NameAndTypeEntry if necessary
