    for (int i = 0; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        if (i == minLabel) {
            for (int vertex : bucket) {
                labels.set(vertex, 0);
            }
            bucketsByLabel.set(i, Collections.emptySet());
        } else {
            for (int vertex : bucket) {
                labels.set(vertex, i);
            }
        }
    }
}

