private Class findClass(final String className) throws ClassNotFoundException {
    for (Class clazz : this.getClass().getClassLoader().getDefinedClasses()) {
        if (clazz.getName().equals(className)) {
            return clazz;
        }
    }
    throw new ClassNotFoundException("Class " + className + " not found");
}

private Class findClass(final String className) throws ClassNotFoundException {
    // Check if the class is already loaded
    Class result = null;
    if (loadedClasses.containsKey(className)) {
        return loadedClasses.get(className);
    }

    // If not, try to load the class from the current classpath
    try {
        result = Class.forName(className);
    } catch (ClassNotFoundException e) {
        // Class not found, try to load it from the parent classloader
        if (getParent() != null) {
            result = getParent().findClass(className);
        } else {
            // Class not found in any classloader, throw exception
            throw new ClassNotFoundException("Class not found: " + className);
        }
    }

    // Add the class to the loadedClasses map
    loadedClasses.put(className, result);

    return result;
}

