public Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSum = new ArrayList<Integer>();
    long totalSum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        totalSum += bounds.get(i);
        suffixSum.add(totalSum);
    }
    return Pair.of(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int[] suffixSums = new int[bounds.size()];
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSums[i] = sum;
    }
    return new Pair<>(suffixSums, sum);
}

