        if (graph == null || vertices.isEmpty()) {
            return false;
        }

        // Check if the vertices induce a clique in the graph
        return graph.getNumberOfVertices() == vertices.size() && graph.getNumberOfEdges() == vertices.size() * (vertices.size() - 1) / 2;
    }

