    for (V vertex : vertexSet) {
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }
    return true;
}

public List<Integer> computeLowerBounds(List<K> keys) {
    if (keys.size() == 0) {
        return Collections.emptyList();
    }
    Collections.sort(keys);
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        Integer lowerBound = key;
        for (int j = i + 1; j < keys.size(); j++) {
            K nextKey = keys.get(j);
            if (key.compareTo(nextKey) > 0) {
                break;
            }
            lowerBound = Math.min(lowerBound, nextKey);
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    Collections.sort(keys);
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        int lowerBound = i;
        while (lowerBound > 0 && keys.get(lowerBound - 1).equals(keys.get(lowerBound))) {
            lowerBound--;
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

