    }

    // If the descriptor represents a method type, increment the number of types to pop
    if (descriptor.charAt(descriptor.length() - 1) == ')') {
        numTypesToPop++;
    }

    // Pop the appropriate number of types from the output frame stack
    for (int i = 0; i < numTypesToPop; i++) {
        outputFrameStack.pop();
    }
}

