public static String applyRelativePath(String path, String relativePath) {
    if (!relativePath.startsWith("/")) {
        throw new IllegalArgumentException("The relative path must start with a '/' character.");
    }
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    int partIndex = pathParts.length - 1;
    for (int i = relativeParts.length - 1; i >= 0; i--) {
        String part = relativeParts[i];
        if (part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (partIndex == 0) {
                throw new IllegalArgumentException("The relative path cannot resolve to a path outside of the root directory.");
            }
            partIndex--;
        } else {
            pathParts[partIndex++] = part;
        }
    }
    return String.join("/", pathParts);
}

