public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            if (tokens.length < 7) {
                continue;
            }

            long threadId = Long.parseLong(tokens[0]);
            String threadName = tokens[1];
            long startTime = Long.parseLong(tokens[2]);
            long endTime = Long.parseLong(tokens[3]);

            // Check if the thread falls within the time range
            if (startTime < timeRanges.get(0).getStartTime() || endTime > timeRanges.get(0).getEndTime()) {
                continue;
            }

            // Parse the thread stack trace
            String[] stackTraceTokens = tokens[4].split(";");
            List<String> stackTrace = new ArrayList<>();
            for (String stackTraceToken : stackTraceTokens) {
                stackTrace.add(stackTraceToken);
            }

            // Create a new thread snapshot for the thread
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadName, startTime, stackTrace);
            threadSnapshots.add(threadSnapshot);
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists()) {
        throw new IllegalArgumentException("The file does not exist.");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line = reader.readLine();
        while (line != null) {
            ThreadSnapshot snapshot = ThreadSnapshot.parseFromLine(line);
            if (snapshot != null && isInRange(snapshot.getTimestamp(), timeRanges)) {
                threadSnapshots.add(snapshot);
            }
            line = reader.readLine();
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String currLine;
        while ((currLine = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = ThreadSnapshot.parse(currLine);
            if (threadSnapshot != null && threadSnapshot.isInTimeRange(timeRanges)) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
            if (threadSnapshot != null) {
                boolean isInTimeRange = false;
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (threadSnapshot.getDate().after(timeRange.getStartDate()) && threadSnapshot.getDate().before(timeRange.getEndDate())) {
                        isInTimeRange = true;
                        break;
                    }
                }
                if (isInTimeRange) {
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
    return threadSnapshots;
}
